import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"周易闡真 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"周易闡真 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"classics/chanzhen/003.md","filePath":"classics/chanzhen/003.md"}'),s={name:"classics/chanzhen/003.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：至哉坤元，萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸亨。牝馬地類，行地無疆，柔順利貞。君子攸行，先迷失道，後順得常。西南得朋，乃與類行；東北喪朋，乃終有慶。安貞之吉，應地無疆。</p></blockquote><h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>初六：履霜，堅冰至。</p><p>六二：直方大，不習無不利。</p><p>六三：含章可貞，或從王事，無成有終。</p><p>六四：括囊，無咎無譽。</p><p>六五：黃裳，元吉。</p><p>上六：龍戰於野，其血玄黃。</p><p>用六：利永貞。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：地勢坤，君子以厚德載物。</p><p>坤為地，其德順，上坤地，下坤地。上者，地之高；下者，地之低。是地勢隨高就低，坤順之象也。</p><p>君子有見於此，知人資地之氣而生，即具此地之順德，因其知識一開，誤用聰明，順非所順，順其氣質之性，失其至善之性，內而不能虛己，外而不能容物，以假為真，以苦為樂，終歸大化，以是法地之順道，而厚德載物焉。厚德即順德，順德厚德即內虛外實之德。惟順能虛，惟厚能實。內虛者，虛心也，虛心而能容物；外實者，實行也，實行而能應物。容物應物，是能載物。物無窮，而載之亦無窮。其德愈載愈厚，愈厚愈載。君子能載物，君子有厚德也。但載物順境去的，逆境去不得，不謂之厚；外面強行，內裡不虛，亦不謂之厚。載物之厚德，須要在真履實踐處做出，如人罵也受的，人打也受的，至於艱難困苦、疾病災患，一切不順境遇，無不一一受的，亦若地之山嶽之重也受的，河海之決也受的，草木之傷也受的。地之厚德如是，君子之厚德亦如是；地之載物如是，君子之載物亦如是。一厚德而修性之功盡矣，此法地之學也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>坤者，順也，柔順卑下之義。卦體六爻皆偶，純陰之象，故謂坤。此運陰符之卦，修性之學，所以行順而用柔道也。順莫順乎地，地本至陰，無陽不能生成萬物。其所以生成萬物者，順乎天之陽氣，進退而生成之，是地本不元亨，而元亨之利，在於能貞耳。地之順天不可見，觀於牝馬之順，而地之順可知矣。</p><p>牝者，陰柔之總名。凡物之陰者，皆屬牝。馬為健行之物，牝馬順牡馬而行，則牝馬所到之處，即是牡馬能到之處，雖柔亦剛，地順之利貞，亦如牝馬之利貞耳。</p><p>人受地之陰氣以成形，即具此柔順之德。柔順之德，即人生之初，秉彝之良能，此能交於後天，為氣質所拘，積習所染，順非所順，順其所欲，良能變為假能矣。</p><p>聖人教人行順道者，由假順而變為真順，還其當日不識不知，順帝之則之本面耳。故曰：“君子有攸往，先迷後得，主。”</p><p>夫剛為柔之主，剛能統柔，柔不能統剛，亦只順承其剛而已。以柔順剛，不但無能者順有能，凡返邪歸正，改惡遷善，存誠去要，以人心順道心之事，皆系以柔順剛之義。先迷者，人心用事，道心埋藏，順其人慾，以假傷真，由迷而失主也。後得主者，道心用事，人心安靜，順其天理，以真滅假，得主而不迷也。</p><p>人能由迷生悟，以陰順陽，借人心複道心，以道心制人心，先失主而後得主，雖愚必明，雖柔必強，何病於柔乎?</p><p>順之道，莫大於地；順之象，莫著於月。月本純陰無陽，與日會於虛危之處，行至西南坤位，初三吐蛾眉之光，魄中生魂，是謂得朋。至於十五，光輝盈輪。十六日景，自此漸錯，月光至此漸退。魂中生魄，行至東北艮地，二十八餘光於此全消，所謂喪朋。</p><p>西南月光方生，陰順其陽之進也。東北月光全消，陰順其陽之退也。陽進則月明，陽退則月昏。月之昏明，亦順其日之進退耳。</p><p>修道君子，用順而行柔道，能如月之順日，則知得知喪，進之退之，無有不利者也。利者何利?利其順之得正，尤利其安居於正，方是全始全終之吉道。</p><p>曰“安貞”者，安正也。以正而安，止於其所，不順而必期其順，不正而必至於正。</p><p>煉己持心，拔去一切輪迴種子，不使有一點滓質留於方寸之中，虛極靜篤，人心不起，道心即生，貞下起元，柔即是剛，順即能健，元而未有不亨，亨而未有不利，利而未有不吉者。安貞之順，豈小焉哉!</p><p>初六，在順之初，系可真可假之際，稍有不正，客氣潛入，必至一陰生而群陰畢集，即有履霜堅冰至之象，故順之須謹於始也。</p><p>六二，柔順中正，中則其心直而能謹慎，正則其行事而有裁製，內直外方，循規蹈矩，自能大其德業，故不習無不利也。</p><p>六三，性柔志剛，含藏章美，順守其正，不以外假而傷內真，即有事而不得不外順者，其必或從王事，欲順於人，不失於己，故無成而能有終也。</p><p>六四，以柔居柔，內念不出，外念不入，順時順命，不致禍而不求福，如括結囊口，內外一空，故無咎而亦無譽也。</p><p>六五，柔順虛中，德足服人，不言而信，不教而化，如黃裳著體，闇然日章，美德在內，自著於外，故為順道之元吉也。</p><p>上六，自尊自大，以柔為剛，不能順人，欲人順己，如龍戰於野，乖和失中，陰差陽錯，未得於人，早傷其己，故其血玄黃也。</p><p>觀於六爻之順，是非不等，邪正各別。求其順之而得利於己者，其惟六二；順之而能感化人者，其惟六五乎？</p><p>噫!順道豈易能哉?毫髮之差，千里之失，不謹於始，必敗於終。聖人大書特書曰：“用六，利永貞。”為後人開一大道，使行順道者永於貞，方能順之得真，方能順之得利。</p><p>夫用六之道，用順道也。六為河圖二四陰生之數，陰主順用。六者用順也，用順所以以虛求實，以無求有耳。</p><p>古今學人，自恃聰明，依一己之見，妄猜私議，不肯低心下氣，求人請益，以故皓首窮年，一無所得。或亦有尋師訪友，不能辨別邪正，入於旁門曲徑，至死不悟者；或有能辨別其邪正，究明性命之理，遵道而行，又半途而廢，不永於貞者。凡此皆非用六之道，俱不能成道。若欲成道，須要知順，又須要順其正，更需要永順其正。能永順其正，柔中即有剛，不隱不瞞，至死不變，脫去後天氣質之性，露出先天不識不知、順帝之則之本面，性了而命亦可了，一永貞而柔順之道至矣，盡矣。</p>',35)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
